mapper.select:
select a.client_id as clientId, max(a.overdue_days) as curMaxOverdueDays, sum(a.overdue_amount) as overdueRent, b.lateCharge as lateCharge from (select id, client_id, contract_id, phase, (if(isnull(plan_collection_amount), 0, plan_collection_amount) - if(isnull(collection_amount), 0, collection_amount)) as overdue_amount, TIMESTAMPDIFF(DAY,plan_collection_date, DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%S')) as overdue_days from collection_base_info where ((ifnull(principal,0) > ifnull(collection_principal,0)) or (ifnull(interest,0) > ifnull(collection_interest,0))) and cash_flow_item = 'RENT' AND plan_collection_date < CURRENT_DATE) a left join ( select client_id, sum(ifnull(penalty_interest, 0)) - sum(ifnull(collection_penalty_interest, 0)) as lateCharge from collection_base_info group by client_id ) as b on a.client_id = b.client_id
and a.client_id in
#{clientId}
group by clientId;
